def esc(value):
    return html.escape(str(value))


def load_dataset(raw):
    data = validate_data(raw)
    ticks = timeline(data)
    playback = data.get('metadata', {}).get('playback', {})
    default = data.get('metadata', {}).get('default_batch_id')
    bid = default if default in [b['id'] for b in data['batches']] else data['batches'][0]['id']
    batch = next(b for b in data['batches'] if b['id'] == bid)
    ss = st.session_state
    ss.update(app_revision=APP_REVISION, data=data, ticks=ticks, index=0, batch_id=bid, batch_choice=bid,
              selected_stage=batch['stages'][0]['id'], follow_active=True, follow_control=True, playing=False,
              speed=float(playback.get('recommended_seconds_per_step', 1)),
              last_tick=time.monotonic(), actions=[], run_id=str(time.time_ns()))


def active_stage(batch, now):
    return next((s for s in batch['stages'] if dt(s['start_at']) <= now <= dt(s['end_at'])), None)


def select_stage(sid):
    st.session_state.selected_stage = sid
    st.session_state.follow_active = False
    st.session_state.follow_control = False


def change_follow():
    st.session_state.follow_active = st.session_state.follow_control


def jump_to_incident(timestamp, stage_id):
    ss = st.session_state
    ss.index = next(index for index, tick in enumerate(ss.ticks) if tick >= dt(timestamp))
    ss.playing = False
    ss.selected_stage = stage_id
    ss.follow_active = False
    ss.follow_control = False
    ss.last_tick = time.monotonic()


def change_batch():
    ss = st.session_state
    ss.batch_id = ss.batch_choice
    batch = next(b for b in ss.data['batches'] if b['id'] == ss.batch_id)
    current = active_stage(batch, ss.ticks[ss.index])
    ss.selected_stage = current['id'] if current else batch['stages'][0]['id']
    ss.follow_active = True
    ss.follow_control = True


COW_ICON_DATA = "data:image/png;base64,"


SVG_PATHS = {
    'milking':'<path d="M4 21V8l8-5 8 5v13H4Z M9 21v-7h6v7 M8 9h.01 M16 9h.01"/>',
    'initial_cooling':'<path d="M12 2v20 M3.3 7l17.4 10 M3.3 17 20.7 7 M9 4l3 3 3-3 M9 20l3-3 3 3"/>',
    'farm_storage':'<ellipse cx="12" cy="5" rx="7" ry="3"/><path d="M5 5v14c0 4 14 4 14 0V5 M5 12c0 4 14 4 14 0"/>',
    'loading':'<path d="M3 8h10v11H3z M13 12h5l3 4v3h-8 M8 3v8 M5 8l3 3 3-3"/><circle cx="6" cy="20" r="2"/><circle cx="18" cy="20" r="2"/>',
    'transport':'<path d="M2 5h12v13H2z M14 10h4l4 5v3h-8"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="19" r="2"/>',
    'delivery_storage':'<path d="M3 21V8l9-5 9 5v13H3Z M7 21V11h10v10 M7 15h10 M7 18h10"/>'}


def stage_bottle(stage_id, index, progress, severity, waiting):
    shade = '#c6dce9' if waiting else '#f4a8b7' if severity == 'critical' else '#f3c477' if severity == 'warning' else '#70c3f6'
    light = '#e2edf5' if waiting else '#ffdde3' if severity == 'critical' else '#fff0cf' if severity == 'warning' else '#c8edff'
    waterline = 130 - (17 if waiting else max(8, progress * .52))
    paths = {
        'initial_cooling': '<path d="M12 2v20M3.3 7l17.4 10M3.3 17 20.7 7M9 4l3 3 3-3M9 20l3-3 3 3M3 10l4-1 1-4M21 14l-4 1-1 4"/>',
        'farm_storage': '<path d="m2 10 10-8 10 8M5 9v13h14V9M9 22v-8h6v8M2 7l10-7 10 7"/>',
        'loading': '<path d="M1 5h13v12H1zM14 9h4l5 5v3h-9"/><circle cx="5" cy="18" r="2.5"/><circle cx="18" cy="18" r="2.5"/>',
        'transport': '<path d="M12 23S3 13 3 8a9 9 0 0 1 18 0c0 5-9 15-9 15Z" fill="currentColor" stroke="none"/><circle cx="12" cy="8" r="3" fill="white" stroke="none"/>',
    }
    symbol = (f'<image href="{COW_ICON_DATA}" x="22" y="43" width="44" height="44"/>' if stage_id == 'milking' else
              f'<svg x="24" y="46" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" color="#719ab6">{paths.get(stage_id, paths["farm_storage"])}</svg>')
    outline = 'M33 22H55C57 26 80 25 80 40V122Q80 137 66 137H22Q8 137 8 122V40C8 25 31 26 33 22Z'
    return (f'<svg class="bottle" viewBox="0 0 88 150" aria-hidden="true"><defs>'
            f'<clipPath id="bottle-clip-{index}"><path d="{outline}"/></clipPath>'
            f'<linearGradient id="water-{index}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="{light}"/><stop offset="1" stop-color="{shade}"/></linearGradient>'
            f'<linearGradient id="glass-{index}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#ffffff"/><stop offset="1" stop-color="#edf6fc"/></linearGradient></defs>'
            '<rect x="34" y="7" width="22" height="5" rx="2" fill="#e8f4fc" stroke="#143d5b" stroke-width="2"/><path d="M38 12v10m14-10v10" stroke="#143d5b" stroke-width="2"/>'
            '<rect x="25" y="136" width="38" height="10" rx="2" fill="#d4e7f4" stroke="#143d5b" stroke-width="2"/>'
            f'<path d="{outline}" fill="url(#glass-{index})"/>'
            f'<g clip-path="url(#bottle-clip-{index})"><path d="M0 {waterline:g} Q20 {waterline-5:g} 44 {waterline:g} T88 {waterline:g} V150H0Z" fill="url(#water-{index})"/>'
            f'<path d="M17 43v68" stroke="white" stroke-width="3" opacity=".6" stroke-linecap="round"/></g>{symbol}'
            f'<path d="{outline}" fill="none" stroke="#143d5b" stroke-width="2.3"/></svg>')


def render_cards(data, batch, now, current, incidents):
    ss = st.session_state
    st.markdown('<div class="sectionline"><strong>Batch journey</strong><span>Click a stage to inspect</span></div>', unsafe_allow_html=True)
    columns = st.columns(len(batch['stages']), gap='small')
    styles = []
    for index, stage in enumerate(batch['stages']):
        rows = stage_rows(data, batch['id'], stage['id'], now)
        status = state_for(stage, rows, now)
        completed = now >= dt(stage['end_at'])
        delivered = stage['id'] == 'transport' and completed
        phase = 'Delivered' if delivered else 'Completed' if completed else 'Active' if current and current['id'] == stage['id'] else 'Upcoming'
        stage_incidents = incidents_for(data, batch, stage, now)
        active = [incident for incident in stage_incidents if incident['ended_at'] is None]
        fresh = latest_fresh_reading(stage, rows, now)
        level = risk_level(stage, fresh['temperature_c'], min(now, dt(stage['end_at'])).isoformat()) if fresh else None
        color = {'critical': 'bad', 'warning': 'warning', 'ideal': 'good'}.get(level, 'neutral')
        severity = 'critical' if any(incident['severity'] == 'critical' for incident in active) else 'warning' if active else None
        ph_reading = latest_fresh_ph(stage, rows, now)
        ph = ph_reading['milk_ph'] if ph_reading else None
        acidity = PH_LABELS[ph_level(ph)] if status != 'waiting' else 'Waiting'
        held_here = any(item.get('hold_started_at') and not item['ended_at'] for item in incidents) and (
            (current and current['id'] == stage['id']) or (stage == batch['stages'][-1] and completed))
        if held_here or ph_level(ph) == 'hold':
            severity = 'critical'
        elif ph_level(ph) in ('warning', 'high') and severity is None:
            severity = 'warning'
        phase_class = 'phase-complete' if completed else 'phase-active' if severity == 'critical' else 'phase-warning' if severity else 'phase-running' if phase == 'Active' else ''
        value = f'{fresh["temperature_c"]:.1f}<small> °C</small>' if fresh else 'Waiting' if status == 'waiting' else 'Unknown'
        primary = next((incident for incident in active if incident['source'] == 'Simulated equipment event'), active[-1] if active else None)
        label = ('Delivered with open alerts' if delivered else primary['type']) if active else ''
        if held_here:
            label = 'Delivered · Quality hold' if delivered else 'Quality hold remains open'
        start, end = dt(stage['start_at']), dt(stage['end_at'])
        progress = 0 if now < start else 100 if now >= end else round((now - start).total_seconds() / (end - start).total_seconds() * 100)
        selected = ss.selected_stage == stage['id']
        if selected:
            styles.append(f'.stApp .st-key-card_{index}{{border-color:#00a0b5;box-shadow:0 0 0 1px #00a0b528}}')
        if severity:
            border, background = ('#fa849a', '#fff6f8') if severity == 'critical' else ('#eab25d', '#fffaf0')
            styles.append(f'.stApp .st-key-card_{index}{{border-color:{border};box-shadow:inset 0 0 0 1px {border};background:{background}}}')
        tooltip = esc(stage.get('description', stage['name']))
        bottle = stage_bottle(stage['id'], index, progress, severity, status == 'waiting')
        issue = f'<div class="cardstatus {"bad" if severity == "critical" else "warning"}"><i class="mini-alert"></i><span>{esc(label)}</span></div>' if label else ''
        ph_value = f'{ph:.2f}' if ph is not None else '—'
        ph_row = f'<div class="ph-value {ph_tone(ph)}"><span>pH</span> {ph_value}</div><div class="ph-state {ph_tone(ph)}">{esc(acidity)}</div>'
        body = (f'<div class="cardbody" title="{tooltip}"><div class="stage-grid">{bottle}<div class="stage-details">'
                f'<div class="stagetitle">{esc(stage["name"])}</div><span class="stagephase {phase_class}">{phase}</span>'
                f'<div class="cardvalue {color} {"word" if fresh is None else ""}">{value}</div>{ph_row}{issue}</div></div>'
                f'<div class="card-progress"><div class="progress {severity or ""}"><span style="width:{progress}%"></span></div>'
                f'<span class="progress-number">{progress}%</span></div></div>')
        with columns[index], st.container(key=f'card_{index}'):
            st.markdown(body, unsafe_allow_html=True)
            st.button(f'View {stage["name"]} history', key=f'choose_{index}', width='stretch',
                      on_click=select_stage, args=(stage['id'],))
    st.markdown('<style>'+''.join(styles)+'</style>', unsafe_allow_html=True)


def table_html(rows, stage):
    result = '<div class="reading-wrap"><table class="reading-table"><thead><tr><th>Time</th><th>Stage</th><th>Temperature (°C)</th><th>Temperature status</th><th>Milk pH</th><th>Acidity status</th></tr></thead><tbody>'
    for row in reversed(rows):
        level = risk_level(stage, row['temperature_c'], row['timestamp'])
        color = {'ideal': 'good', 'warning': 'warning', 'critical': 'bad', 'observational': 'neutral'}[level]
        label = {'ideal': 'In range', 'warning': 'Boundary', 'critical': 'Alert', 'observational': 'Observational'}[level]
        result += (f'<tr><td>{dt(row["timestamp"]):%H:%M}</td><td>{esc(stage["name"])}</td>'
                   f'<td class="temp {color}">{row["temperature_c"]:.1f}</td><td><span class="reading-chip {color}">{label}</span></td>'
                   f'<td class="temp {ph_tone(row.get("milk_ph"))}">{format(row["milk_ph"], ".2f") if row.get("milk_ph") is not None else "—"}</td>'
                   f'<td><span class="reading-chip {ph_tone(row.get("milk_ph"))}">{PH_LABELS[ph_level(row.get("milk_ph"))]}</span></td></tr>')
    return result+'</tbody></table></div>'


def journey_log(data, batch, now):
    result = '<div class="reading-wrap"><table class="reading-table"><thead><tr><th>Stage</th><th>Latest sample</th><th>Temperature</th><th>Milk pH</th><th>Acidity status</th></tr></thead><tbody>'
    for stage in batch['stages']:
        rows = stage_rows(data, batch['id'], stage['id'], now)
        fresh = latest_fresh_reading(stage, rows, now)
        ph_row = latest_fresh_ph(stage, rows, now)
        ph = ph_row['milk_ph'] if ph_row else None
        level = risk_level(stage, fresh['temperature_c'], min(now, dt(stage['end_at'])).isoformat()) if fresh else None
        tone = {'critical': 'bad', 'warning': 'warning', 'ideal': 'good'}.get(level, 'neutral')
        value = f'{fresh["temperature_c"]:.1f} °C' if fresh else 'Unknown' if now >= dt(stage['start_at']) else 'Waiting'
        result += (f'<tr><td><b>{esc(stage["name"])}</b></td><td>{dt(rows[-1]["timestamp"]):%H:%M}</td>' if rows else
                   f'<tr><td><b>{esc(stage["name"])}</b></td><td>—</td>')
        result += (f'<td class="temp {tone}">{value}</td><td class="temp {ph_tone(ph)}">{format(ph, ".2f") if ph is not None else "—"}</td>'
                   f'<td><span class="reading-chip {ph_tone(ph)}">{PH_LABELS[ph_level(ph)]}</span></td></tr>')
    return result+'</tbody></table></div>'


def alert_metrics(incidents, actions):
    active = sum(1 for incident in incidents if not incident['ended_at'])
    acknowledged = sum(1 for incident in incidents
                       if incident_action(actions, incident['id'], 'Alert acknowledged'))
    recovered = sum(1 for incident in incidents if incident['ended_at'])
    pending = sum(1 for incident in incidents
                  if not incident_action(actions, incident['id'], 'Incident report completed'))
    return active, acknowledged, recovered, pending


def render_alert_kpis(incidents, actions, compact=False):
    active, acknowledged, recovered, pending = alert_metrics(incidents, actions)
    if compact:
        icons = {
            'danger': '<circle cx="12" cy="12" r="10" fill="currentColor"/><path d="M12 6v7m0 3v1" stroke="white" stroke-width="2"/>',
            'success': '<circle cx="12" cy="12" r="10" fill="currentColor"/><path d="m7 12 3 3 7-7" fill="none" stroke="white" stroke-width="2"/>',
            'record': '<path d="M6 2h9l5 5v15H6zM15 2v6h5M9 12h8M9 16h8" fill="none" stroke="currentColor" stroke-width="1.7"/>',
        }
        columns = st.columns(3, gap='small')
        for index, (label, count, tone) in enumerate([('Active alerts', active, 'danger'), ('Recovered incidents', recovered, 'success'), ('Reports pending', pending, 'record')]):
            with columns[index], st.container(key=f'summary_{index}'):
                st.markdown(f'<div class="summary-card"><div class="summary-icon {tone}"><svg viewBox="0 0 24 24">{icons[tone]}</svg></div><div class="summary-copy"><span>{label}</span><b>{count}</b></div><span class="summary-arrow">›</span></div>', unsafe_allow_html=True)
                st.button(f'View {label.lower()}', key=f'summary_link_{index}', on_click=navigate, args=('Incidents',), width='stretch')
        return
    cards = [('Active alerts', active, 'Needs attention'), ('Acknowledged', acknowledged, 'Seen by operator'),
             ('Recovered', recovered, 'Reading returned'), ('Reports pending', pending, 'Close the record')]
    body = '<div class="alert-kpis">'
    for label, value, helper in cards:
        tone = 'warning' if value and label in ('Active alerts', 'Reports pending') else 'good'
        body += f'<div class="kpi"><span>{label}</span><b class="{tone}">{value}</b><small>{helper}</small></div>'
    st.markdown(body + '</div>', unsafe_allow_html=True)


def render_incident_page(data, batch, incidents, actions, now):
    render_alert_kpis(incidents, actions)
    if not incidents:
        with st.container(key='alert_detail'):
            st.markdown('### No alerts yet')
            st.caption('Track this batch. System-generated alerts will appear here when a reading leaves the ideal range or data becomes unavailable.')
        return

    options = {f'ALT-{number:03d} | {incident["type"]} | {incident["stage"]}': incident
               for number, incident in enumerate(incidents, 1)}
    register, detail = st.columns([.78, 1.42], gap='medium')
    with register, st.container(key='alert_register'):
        st.subheader('Alert register')
        choice = st.selectbox('Choose an alert', list(reversed(options)), label_visibility='collapsed')
        selected = options[choice]
        rows = []
        for label, incident in reversed(list(options.items())):
            rows.append({'Alert': label.split(' | ')[0], 'Issue': incident['type'],
                         'Time': dt(incident['started_at']).strftime('%H:%M'),
                         'Status': incident_status(incident, actions)})
        listing = '<table class="reading-table"><thead><tr><th>Alert</th><th>Time</th><th>Status</th></tr></thead><tbody>'
        for row in rows:
            tone = 'warning' if row['Status'] in ('Active alert', 'Acknowledged') else 'good'
            listing += (f'<tr><td><b>{esc(row["Alert"])}</b><br><small>{esc(row["Issue"])}</small></td>'
                        f'<td>{esc(row["Time"])}</td><td class="{tone}">{esc(row["Status"])}</td></tr>')
        st.markdown(listing + '</tbody></table>', unsafe_allow_html=True)

    with detail, st.container(key='alert_detail'):
        selected_number = list(options.values()).index(selected) + 1
        alert_id = f'ALT-{selected_number:03d}'
        status = incident_status(selected, actions)
        stage = next(stage for stage in batch['stages'] if stage['id'] == selected['stage_id'])
        rows = stage_rows(data, batch['id'], stage['id'], now)
        fresh = latest_fresh_reading(stage, rows, now)
        latest = f'{fresh["temperature_c"]:.1f} °C' if fresh else 'Unknown (no fresh reading)'
        if selected.get('category') == 'milk_ph':
            ph_row = batch_ph_reading(data, batch, now)
            latest = f'pH {ph_row["milk_ph"]:.2f} · {PH_LABELS[ph_level(ph_row["milk_ph"])]}' if ph_row else 'Unknown (no fresh pH reading)'
        flag = 0 if selected['ended_at'] else 1
        st.markdown(
            f'<div class="alert-detail-head"><div><div class="alert-id">{alert_id}</div>'
            f'<div class="alert-title">{esc(selected["type"])}</div></div>'
            f'<span class="status-chip">{esc(status)}</span></div>'
            f'<div class="detail-grid"><div><span>Batch</span><b>{esc(batch["id"])}</b></div>'
            f'<div><span>Alert flag</span><b>{flag}</b></div>'
            f'<div><span>Stage</span><b>{esc(selected["stage"])}</b></div>'
            f'<div><span>Location</span><b>{esc(stage.get("location", "Unknown"))}</b></div>'
            f'<div><span>Detected</span><b>{dt(selected["started_at"]):%d %b, %H:%M}</b></div>'
            f'<div><span>Latest reading</span><b>{latest}</b></div>'
            f'<div><span>Container / vehicle</span><b>{esc(batch.get("container_id") or batch.get("vehicle_id", "Unassigned"))}</b></div>'
            f'<div><span>Operator</span><b>{esc(batch["owner"])}</b></div></div>', unsafe_allow_html=True)
        st.caption(f'{selected["severity"].title()} · {selected["source"]}')
        st.write(selected['description'])
        if selected.get('hold_started_at'):
            st.caption(f'Hold escalated in {selected["hold_stage"]} at {dt(selected["hold_started_at"]):%H:%M}. Delivery status does not release a quality hold.')
        guidance = INCIDENT_GUIDANCE.get(selected['type'], INCIDENT_GUIDANCE['High temperature'])
        st.markdown('<div class="steps">' + ''.join(
            f'<div class="step"><b>Step {index}</b>{esc(item)}</div>'
            for index, item in enumerate(guidance, 1)) + '</div>', unsafe_allow_html=True)
        acknowledged = bool(incident_action(actions, selected['id'], 'Alert acknowledged'))
        complete = bool(incident_action(actions, selected['id'], 'Incident report completed'))
        first, second = st.columns(2)
        if first.button('Acknowledged' if acknowledged else 'Acknowledge alert',
                        disabled=acknowledged, type='primary' if not acknowledged else 'secondary',
                        width='stretch', key=f'ack_{selected_number}'):
            st.session_state.actions.append(dict(timestamp=now.isoformat(), batch_id=batch['id'],
                incident_id=selected['id'], actor=batch['owner'], type='Alert acknowledged',
                note='Operator confirmed the system alert.'))
            st.rerun()
        if second.button('Report complete' if complete else 'Complete incident report',
                         disabled=complete or not acknowledged or selected['ended_at'] is None, width='stretch', key=f'close_{selected_number}'):
            st.session_state.actions.append(dict(timestamp=now.isoformat(), batch_id=batch['id'],
                incident_id=selected['id'], actor=batch['owner'], type='Incident report completed',
                note='Incident details reviewed and record completed.'))
            st.rerun()
        if not acknowledged:
            st.caption('Acknowledge the system alert before completing its report.')
        elif selected['ended_at'] is None:
            st.caption('Recovery must be confirmed before the incident report can be completed.')
        if selected.get('hold_started_at') and not selected['ended_at']:
            st.markdown('#### Simulated quality clearance')
            ph_row = batch_ph_reading(data, batch, now)
            expected = ph_row is not None and ph_level(ph_row['milk_ph']) == 'expected'
            reviewed = st.checkbox('Simulated sample verified and quality officer approves release', key=f'review_{selected["id"]}')
            note = st.text_input('Quality officer review note', key=f'review_note_{selected["id"]}', max_chars=500)
            st.caption('Demo workflow only. A fresh expected-band pH and recorded review are required; this is not food-safety certification.')
            if not expected:
                st.caption('Release unavailable: there is no fresh pH sample in the expected 6.60–6.80 band.')
            if st.button('Record simulated hold release', disabled=not (acknowledged and expected and reviewed and note.strip()), key=f'release_{selected["id"]}'):
                st.session_state.actions.append(dict(timestamp=now.isoformat(), batch_id=batch['id'], incident_id=selected['id'],
                    actor=batch['owner'], type='Quality hold released', review_confirmed=True, note=note.strip(), sample_timestamp=ph_row['timestamp']))
                st.rerun()


def render_demo_page():
    ss = st.session_state
    with st.container(key='demo_panel'):
        st.subheader('Data')
        st.caption('Upload another simulated journey or reset this proof of concept to the bundled sample.')
        st.caption('Five stages: milking → initial cooling → farm storage → loading → transport / delivered.')
        st.caption('Optional reading fields: milk_ph (number from 0 to 14, or null) and ph_device_id. Older temperature-only files show unknown pH.')
        st.info('Demo pH bands: 6.60–6.80 expected (green); 6.40–<6.60 mild acidity warning (orange). Accelerated simulation at a common 20 °C reference. pH indicates acidity, not drinkability. Other out-of-band values are flagged separately when present.')
        upload = st.file_uploader('Upload journey JSON', type=['json'], max_upload_size=2, key='upload')
        if upload is not None:
            fingerprint = hashlib.sha256(upload.getvalue()).hexdigest()
            if fingerprint != ss.get('upload_fingerprint'):
                try:
                    load_dataset(json.loads(upload.getvalue().decode('utf-8-sig')))
                    ss.upload_fingerprint = fingerprint
                    st.success('Data loaded. Choose Overview, then Track batch.')
                except (ValueError, KeyError, TypeError) as exc:
                    st.error(f'Cannot load this file: {exc}')
        reset, sample = st.columns(2)
        if reset.button('Load bundled sample', width='stretch', type='primary'):
            load_dataset(json.loads((ROOT/'sample_data.json').read_text(encoding='utf-8')))
            if upload is not None:
                ss.upload_fingerprint = hashlib.sha256(upload.getvalue()).hexdigest()
            st.rerun()
        sample.download_button('Download current dataset', json.dumps(ss.data, indent=2),
                               'sample_data.json', 'application/json', width='stretch')
        ss.speed = st.select_slider('Playback speed: seconds per simulated minute',
                                    options=[.5, 1., 2., 3., 5.], value=ss.speed)
        st.markdown(f'**{len(ss.data["batches"])} batches**  ·  **{len(ss.data["readings"])} readings**  ·  No physical sensor required')

        st.subheader('Demo scenario guide')
        st.caption('Planned scenarios only. Alerts appear when replay reaches their detection time.')
        guide = []
        for batch in ss.data['batches']:
            item = {'Batch': batch['id']}
            item['Name'] = batch.get('display_name', batch['id'])
            item['pH scenario'] = batch.get('ph_scenario', 'No pH scenario supplied')
            for stage in batch['stages']:
                item[stage['name']] = stage.get('demo_issue', 'See journey readings')
            guide.append(item)
        st.dataframe(guide, hide_index=True, width='stretch')


def navigate(page):
    st.session_state.page = page


def seek_replay():
    st.session_state.index = st.session_state.replay_position
    st.session_state.last_tick = time.monotonic()


def render_masthead(batch, batches, now, incidents):
    ss = st.session_state
    page = ss.get('page', 'Overview')
    with st.container(key='masthead'):
        brand, content = st.columns([.32, .68], vertical_alignment='top', gap='large')
        with brand:
            logo = ROOT / 'logo-mark-transparent.png'
            img = f'<img alt="Two Degrees logo" src="data:image/png;base64,{__import__("base64").b64encode(logo.read_bytes()).decode()}">' if logo.exists() else ''
            st.markdown(f'<div class="brand">{img}<div><strong>Two Degrees</strong><small>COLD-CHAIN RESILIENCE</small></div></div>', unsafe_allow_html=True)
        with content:
            with st.container(key='nav'):
                links = st.columns(4, gap='small')
                for column, target in zip(links, ['Overview', 'Incidents', 'Records', 'Data']):
                    if column.button(target, key='nav_' + target.lower(), type='primary' if page == target else 'secondary', width='stretch'):
                        ss.page = target
                        if target == 'Data':
                            ss.playing = False
                        st.rerun()
            title, clock = st.columns([4.4, 1], vertical_alignment='center', gap='small')
            with title:
                heading = 'Data' if page == 'Data' else 'Milk journey monitoring'
                st.markdown(f'<div class="eyebrow">FROM FARM TO DELIVERY</div><div class="titleline"><h1>{heading}</h1><span class="pill">SIMULATED DATA</span></div>', unsafe_allow_html=True)
            with clock:
                mode = 'Playing' if ss.playing else 'Finished' if ss.index == len(ss.ticks)-1 else 'Paused'
                st.markdown(f'<div class="clock">{now:%d %b %Y}<br><b>{now:%H:%M}</b> · {mode}</div>', unsafe_allow_html=True)
            if page == 'Data':
                st.caption('Upload a journey dataset, explore the demonstration scenarios, or choose playback speed.')
            else:
                with st.container(key='context'):
                    pick, details = st.columns([1, 3], vertical_alignment='center', gap='medium')
                    with pick:
                        st.selectbox('Batch', list(batches), key='batch_choice', on_change=change_batch,
                                     format_func=lambda bid: f'{bid} · {batches[bid]["display_name"]}' if batches[bid].get('display_name') else bid,
                                     label_visibility='collapsed', help=batch.get('scenario', 'Uploaded batch'))
                    with details:
                        active = sum(incident['ended_at'] is None for incident in incidents)
                        origin = batch['origin'].replace(' (Demo)', '').replace(' Dairy', '')
                        destination = batch['destination'].replace(' (Demo)', '').replace(' Dairy Hub', '')
                        message = f'{active} active alert' + ('s' if active != 1 else '')
                        holds = sum(bool(incident.get('hold_started_at')) and not incident['ended_at'] for incident in incidents)
                        if holds:
                            message = f'{holds} quality hold' + ('s' if holds != 1 else '')
                        st.markdown(f'<div class="summary"><div><span>Volume</span><b>{batch["quantity_litres"]:g} L</b></div><div class="route"><span>Route</span><b>{esc(origin)} → {esc(destination)}</b></div><div><span>Vehicle</span><b>{esc(batch.get("vehicle_id", "Unassigned"))}</b></div><div class="header-alert {"clear" if not active else ""}"><i>{"✓" if not active else "!"}</i>{message}</div></div>', unsafe_allow_html=True)


def render_replay_controls(data, batch, now):
    ss = st.session_state
    planned = all_incidents(data, batch, ss.ticks[-1])
    milestones = [(item['started_at'], item['stage_id']) for item in planned]
    milestones += [(item['hold_started_at'], item['hold_stage_id']) for item in planned if item.get('hold_started_at')]
    upcoming = next((item for item in sorted(set(milestones), key=lambda item: dt(item[0])) if dt(item[0]) > now), None)
    with st.container(key='replay'):
        fill = ss.index / max(1, len(ss.ticks)-1) * 100
        st.markdown(f'<style>.st-key-replay{{--replay-fill:{fill:g}%}}</style>', unsafe_allow_html=True)
        play, next_column, restart, seek, follow, jump = st.columns([1.15, .95, .85, 2.6, 1.2, 1], gap='small', vertical_alignment='center')
        if play.button('Pause tracking' if ss.playing else 'Track batch', type='primary', width='stretch', disabled=ss.index == len(ss.ticks)-1):
            ss.playing = not ss.playing
            ss.last_tick = time.monotonic()
            st.rerun()
        if next_column.button('Next update', width='stretch', disabled=ss.playing or ss.index == len(ss.ticks)-1):
            ss.index += 1
            ss.last_tick = time.monotonic()
            st.rerun()
        if restart.button('Restart', width='stretch'):
            ss.index = 0
            ss.playing = False
            ss.actions = []
            ss.run_id = str(time.time_ns())
            ss.follow_active = True
            ss.follow_control = True
            ss.selected_stage = batch['stages'][0]['id']
            ss.last_tick = time.monotonic()
            st.rerun()
        with seek:
            ss.replay_position = ss.index
            if len(ss.ticks) > 1:
                st.slider('Replay position', 0, len(ss.ticks)-1, key='replay_position', disabled=ss.playing,
                          label_visibility='collapsed', on_change=seek_replay)
            else:
                st.caption('Single reading')
        with follow:
            st.toggle('Follow journey', key='follow_control', on_change=change_follow)
        jump.button('Next incident', disabled=upcoming is None, width='stretch',
                    on_click=jump_to_incident, args=upcoming if upcoming else (None, None))


def main():
    st.set_page_config(page_title='Two Degrees | Milk journey', page_icon='🥛', layout='wide', initial_sidebar_state='collapsed')
    st.markdown(CSS, unsafe_allow_html=True)
    ss = st.session_state
    if 'data' not in ss or ss.get('app_revision') != APP_REVISION:
        load_dataset(json.loads((ROOT / 'sample_data.json').read_text(encoding='utf-8')))
    ss.setdefault('follow_active', True)
    ss.setdefault('follow_control', ss.follow_active)

    @st.fragment(run_every=.5 if ss.playing else None)
    def dashboard():
        if ss.playing and time.monotonic() - ss.last_tick >= ss.speed:
            ss.index = min(ss.index + 1, len(ss.ticks)-1)
            ss.last_tick = time.monotonic()
            if ss.index == len(ss.ticks)-1:
                ss.playing = False
                st.rerun()
        now, data = ss.ticks[ss.index], ss.data
        batches = {batch['id']: batch for batch in data['batches']}
        batch = batches[ss.batch_id]
        if 'batch_choice' not in ss:
            ss.batch_choice = ss.batch_id
        current = active_stage(batch, now)
        if ss.follow_active and current:
            ss.selected_stage = current['id']
        actions = [action for action in ss.actions if action['batch_id'] == batch['id'] and dt(action['timestamp']) <= now]
        incidents = all_incidents(data, batch, now, actions)
        events = [event for event in data.get('scenario_events', []) if event['batch_id'] == batch['id'] and dt(event['timestamp']) <= now]
        render_masthead(batch, batches, now, incidents)
        page = ss.get('page', 'Overview')
        if page == 'Data':
            render_demo_page()
            return
        render_replay_controls(data, batch, now)
        if page == 'Records':
            with st.container(key='record_panel'):
                st.subheader(f'{batch["id"]} · Records')
                payload = records_payload(data, batch, now, incidents, actions, events, ss.run_id)
                st.caption(f'{len(payload["readings"])} readings · {len(incidents)} alerts and incidents · {len(actions)} operator records')
                excel, technical = st.columns(2)
                excel.download_button('Export Excel', excel_records(payload), f'{batch["id"]}-records.xlsx',
                                      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', type='primary', width='stretch')
                technical.download_button('Export JSON', json.dumps(payload, indent=2), f'{batch["id"]}-records.json', 'application/json', width='stretch')
                st.caption('Excel is the readable report. JSON keeps the same information for technical use.')
            return
        if page == 'Overview':
            render_cards(data, batch, now, current, incidents)
            render_alert_kpis(incidents, actions, compact=True)
            stage = next(stage for stage in batch['stages'] if stage['id'] == ss.selected_stage)
            rows = stage_rows(data, batch['id'], stage['id'], now)
            status = state_for(stage, rows, now)
            left, right = st.columns(2, gap='small')
            with left, st.container(key='chart_panel'):
                st.subheader('Temperature history')
                st.caption(f'{stage["name"]} · {stage.get("location", "Stage readings")}')
                if rows:
                    st.plotly_chart(graph_for(stage, rows), width='stretch', theme=None, key='history_chart', config={'displayModeBar': False})
                else:
                    st.markdown('<div class="empty">Readings will appear when this stage begins.</div>', unsafe_allow_html=True)
                if status == 'data_unavailable':
                    st.warning('Current temperature is unknown. The graph preserves the gap in readings.')
            with right, st.container(key='ph_panel'):
                st.subheader('Milk pH trend')
                st.caption('Entire journey · Acidity screening · Simulated reference: 20 °C')
                st.plotly_chart(ph_graph(data, batch, now), width='stretch', theme=None, key='ph_history_chart', config={'displayModeBar': False})
                if batch_ph_reading(data, batch, now) is None:
                    st.caption('Current pH is unknown. No normal value is assumed for missing readings.')
                st.markdown(ph_legend(data, batch, now), unsafe_allow_html=True)
            with st.container(key='log_panel'):
                st.subheader('Reading log')
                st.markdown(journey_log(data, batch, now), unsafe_allow_html=True)
                st.caption('Latest fresh stage values. Historical stage values remain visible; the header shows any continuing batch hold.')
                if not rows:
                    st.caption('No readings yet.')
                with st.expander(f'{stage["name"]} · Full history ({len(rows)} readings)'):
                    st.markdown('<div style="max-height:320px;overflow:auto">' + table_html(rows, stage) + '</div>', unsafe_allow_html=True)
                st.download_button('Download stage log', csv_data(rows, stage), f'{batch["id"]}-{stage["id"]}.csv', 'text/csv', width='stretch')
            st.markdown('<div class="legend"><span><i style="background:#00884f"></i>Green: 0 &lt; T &lt; 4 °C</span><span><i style="background:#df911b"></i>Orange: 0 or 4 °C</span><span><i style="background:#dc1738"></i>Red: T &lt; 0 or T &gt; 4 °C</span><span>Warm collection / cooling is observational.</span></div>', unsafe_allow_html=True)
        elif page == 'Incidents':
            st.markdown('<div class="sectionline"><strong>Incident centre</strong></div>', unsafe_allow_html=True)
            with st.container(key='incident_workspace'):
                render_incident_page(data, batch, incidents, actions, now)
        st.markdown('<div class="footer">Two Degrees · Accelerated simulation · pH indicates acidity, not food-safety certification. Cooling recovery does not release a quality hold.</div>', unsafe_allow_html=True)
    dashboard()


if __name__ == '__main__':
    main()
